real_t acado_solve_dim36_system( real_t* const A, real_t* const b, int* const rk_perm )
{
real_t det;

int i;
int j;
int k;

int indexMax;

int intSwap;

real_t valueMax;

real_t temp;

for (i = 0; i < 36; ++i)
{
rk_perm[i] = i;
}
det = 1.0000000000000000e+00;
for( i=0; i < (35); i++ ) {
	indexMax = i;
	valueMax = fabs(A[i*36+i]);
	for( j=(i+1); j < 36; j++ ) {
		temp = fabs(A[j*36+i]);
		if( temp > valueMax ) {
			indexMax = j;
			valueMax = temp;
		}
	}
	if( indexMax > i ) {
for (k = 0; k < 36; ++k)
{
	rk_dim36_swap = A[i*36+k];
	A[i*36+k] = A[indexMax*36+k];
	A[indexMax*36+k] = rk_dim36_swap;
}
	rk_dim36_swap = b[i];
	b[i] = b[indexMax];
	b[indexMax] = rk_dim36_swap;
	intSwap = rk_perm[i];
	rk_perm[i] = rk_perm[indexMax];
	rk_perm[indexMax] = intSwap;
	}
	det *= A[i*36+i];
	for( j=i+1; j < 36; j++ ) {
		A[j*36+i] = -A[j*36+i]/A[i*36+i];
		for( k=i+1; k < 36; k++ ) {
			A[j*36+k] += A[j*36+i] * A[i*36+k];
		}
		b[j] += A[j*36+i] * b[i];
	}
}
det *= A[1295];
det = fabs(det);
acado_solve_dim36_triangular( A, b );
return det;
}

